     1→/**
     2→ * Plan document parser for structured plan files.
     3→ *
     4→ * Parses markdown documents with embedded YAML blocks defining specs and tasks.
     5→ * Supports topological ordering, error recovery, and dry-run mode.
     6→ *
     7→ * AC: @plan-import ac-11 - Parse ## Specs YAML blocks
     8→ * AC: @plan-import ac-12 - Support derive_from_specs flag
     9→ * AC: @plan-import ac-13 - Extract ## Implementation Notes
    10→ */
    11→
    12→import { parse as parseYaml } from "yaml";
    13→import { z } from "zod";
    14→import { AcceptanceCriterionSchema } from "../schema/spec.js";
    15→
    16→/**
    17→ * Spec definition from plan document
    18→ */
    19→export const PlanSpecSchema = z.object({
    20→  title: z.string(),
    21→  slug: z.string().optional(),
    22→  type: z.string().optional(),
    23→  parent: z.string().optional(),
    24→  description: z.string().optional(),
    25→  acceptance_criteria: z.array(AcceptanceCriterionSchema).optional(),
    26→  traits: z.array(z.string()).optional(),
    27→});
    28→
    29→export type PlanSpec = z.infer<typeof PlanSpecSchema>;
    30→
    31→/**
    32→ * Manual task definition from plan document
    33→ */
    34→export const PlanTaskSchema = z.object({
    35→  title: z.string(),
    36→  slug: z.string().optional(),
    37→  priority: z.number().optional(),
    38→  description: z.string().optional(),
    39→  tags: z.array(z.string()).optional(),
    40→});
    41→
    42→export type PlanTask = z.infer<typeof PlanTaskSchema>;
    43→
    44→/**
    45→ * Tasks section configuration
    46→ */
    47→export const TasksSectionSchema = z.object({
    48→  derive_from_specs: z.boolean().optional(),
    49→  additional_tasks: z.array(PlanTaskSchema).optional(),
    50→});
    51→
    52→export type TasksSection = z.infer<typeof TasksSectionSchema>;
    53→
    54→/**
    55→ * Parsed plan document structure
    56→ */
    57→export interface ParsedPlanDocument {
    58→  title: string;
    59→  content: string;
    60→  specs: PlanSpec[];
    61→  tasks: TasksSection;
    62→  implementationNotes: string | null;
    63→  errors: ParseError[];
    64→}
    65→
    66→/**
    67→ * Parse error with context
    68→ */
    69→export interface ParseError {
    70→  type: "yaml" | "validation" | "dependency" | "circular";
    71→  message: string;
    72→  line?: number;
    73→  specIndex?: number;
    74→  spec?: PlanSpec;
    75→}
    76→
    77→/**
    78→ * Parse a plan document from markdown text.
    79→ *
    80→ * AC: @plan-import ac-11 - Extract and parse ## Specs YAML blocks
    81→ * AC: @plan-import ac-12 - Parse Tasks section for derive_from_specs
    82→ * AC: @plan-import ac-13 - Extract ## Implementation Notes section
    83→ * AC: @plan-import ac-21 - Report YAML parse errors with line numbers
    84→ */
    85→export function parsePlanDocument(content: string): ParsedPlanDocument {
    86→  const errors: ParseError[] = [];
    87→
    88→  // Extract title from first heading
    89→  const titleMatch = content.match(/^#\s+(.+)$/m);
    90→  const title = titleMatch ? titleMatch[1].trim() : "Untitled Plan";
    91→
    92→  // Extract ## Specs section
    93→  const specs = extractSpecsSection(content, errors);
    94→
    95→  // Extract ## Tasks section
    96→  const tasks = extractTasksSection(content, errors);
    97→
    98→  // Extract ## Implementation Notes section
    99→  const implementationNotes = extractImplementationNotes(content);
   100→
   101→  return {
   102→    title,
   103→    content,
   104→    specs,
   105→    tasks,
   106→    implementationNotes,
   107→    errors,
   108→  };
   109→}
   110→
   111→/**
   112→ * Extract and parse the ## Specs section.
   113→ *
   114→ * AC: @plan-import ac-11 - Parse YAML array of spec definitions
   115→ * AC: @plan-import ac-21 - Handle YAML parse errors
   116→ * AC: @plan-import ac-22 - Validate required fields
   117→ */
   118→function extractSpecsSection(content: string, errors: ParseError[]): PlanSpec[] {
   119→  // Find ## Specs section
   120→  const specsMatch = content.match(/##\s+Specs\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   121→
   122→  if (!specsMatch) {
   123→    return [];
   124→  }
   125→
   126→  const specsContent = specsMatch[1];
   127→
   128→  // Extract YAML code block
   129→  const yamlMatch = specsContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
   130→
   131→  if (!yamlMatch) {
   132→    return [];
   133→  }
   134→
   135→  const yamlContent = yamlMatch[1];
   136→
   137→  // Parse YAML
   138→  let parsed: unknown;
   139→  try {
   140→    parsed = parseYaml(yamlContent);
   141→  } catch (err) {
   142→    errors.push({
   143→      type: "yaml",
   144→      message: `Malformed YAML in Specs section: ${err instanceof Error ? err.message : String(err)}`,
   145→    });
   146→    return [];
   147→  }
   148→
   149→  // Validate array
   150→  if (!Array.isArray(parsed)) {
   151→    errors.push({
   152→      type: "validation",
   153→      message: "Specs section must contain a YAML array",
   154→    });
   155→    return [];
   156→  }
   157→
   158→  // Validate each spec
   159→  const specs: PlanSpec[] = [];
   160→
   161→  for (let i = 0; i < parsed.length; i++) {
   162→    const spec = parsed[i];
   163→
   164→    // Validate required title field
   165→    if (!spec || typeof spec !== "object" || !("title" in spec)) {
   166→      errors.push({
   167→        type: "validation",
   168→        message: `Spec at index ${i} missing required field: title`,
   169→        specIndex: i,
   170→      });
   171→      continue;
   172→    }
   173→
   174→    // Validate against schema
   175→    const result = PlanSpecSchema.safeParse(spec);
   176→    if (!result.success) {
   177→      errors.push({
   178→        type: "validation",
   179→        message: `Spec at index ${i} validation failed: ${result.error.message}`,
   180→        specIndex: i,
   181→      });
   182→      continue;
   183→    }
   184→
   185→    specs.push(result.data);
   186→  }
   187→
   188→  return specs;
   189→}
   190→
   191→/**
   192→ * Extract and parse the ## Tasks section.
   193→ *
   194→ * AC: @plan-import ac-12 - Parse derive_from_specs flag
   195→ * AC: @plan-import ac-27 - Parse additional_tasks array
   196→ */
   197→function extractTasksSection(content: string, errors: ParseError[]): TasksSection {
   198→  // Find ## Tasks section
   199→  const tasksMatch = content.match(/##\s+Tasks\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   200→
   201→  if (!tasksMatch) {
   202→    return {};
   203→  }
   204→
   205→  const tasksContent = tasksMatch[1].trim();
   206→
   207→  // Check for derive_from_specs flag
   208→  const deriveMatch = tasksContent.match(/^derive_from_specs:\s*(true|false)/m);
   209→  const deriveFromSpecs = deriveMatch ? deriveMatch[1] === "true" : undefined;
   210→
   211→  // Extract YAML code block for additional tasks
   212→  const yamlMatch = tasksContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
   213→
   214→  let additionalTasks: PlanTask[] | undefined;
   215→
   216→  if (yamlMatch) {
   217→    const yamlContent = yamlMatch[1];
   218→
   219→    try {
   220→      const parsed = parseYaml(yamlContent);
   221→
   222→      if (Array.isArray(parsed)) {
   223→        additionalTasks = [];
   224→        for (let i = 0; i < parsed.length; i++) {
   225→          const result = PlanTaskSchema.safeParse(parsed[i]);
   226→          if (!result.success) {
   227→            errors.push({
   228→              type: "validation",
   229→              message: `Task at index ${i} validation failed: ${result.error.message}`,
   230→            });
   231→            continue;
   232→          }
   233→          additionalTasks.push(result.data);
   234→        }
   235→      }
   236→    } catch (err) {
   237→      errors.push({
   238→        type: "yaml",
   239→        message: `Malformed YAML in Tasks section: ${err instanceof Error ? err.message : String(err)}`,
   240→      });
   241→    }
   242→  }
   243→
   244→  return {
   245→    derive_from_specs: deriveFromSpecs,
   246→    additional_tasks: additionalTasks,
   247→  };
   248→}
   249→
   250→/**
   251→ * Extract ## Implementation Notes section.
   252→ *
   253→ * AC: @plan-import ac-13 - Extract implementation notes as plain text
   254→ */
   255→function extractImplementationNotes(content: string): string | null {
   256→  const notesMatch = content.match(/##\s+Implementation\s+Notes\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   257→
   258→  if (!notesMatch) {
   259→    return null;
   260→  }
   261→
   262→  return notesMatch[1].trim();
   263→}
   264→
   265→/**
   266→ * Sort specs in topological order (parents before children).
   267→ *
   268→ * AC: @plan-import ac-16 - Create specs in dependency order
   269→ * AC: @plan-import ac-18 - Detect circular dependencies
   270→ *
   271→ * @returns Sorted specs or null if circular dependency detected
   272→ */
   273→export function topologicalSort(
   274→  specs: PlanSpec[],
   275→): { sorted: PlanSpec[]; error: ParseError | null } {
   276→  // Build adjacency list
   277→  const graph = new Map<string, string[]>();
   278→  const specBySlug = new Map<string, PlanSpec>();
   279→
   280→  for (const spec of specs) {
   281→    const slug = spec.slug || slugify(spec.title);
   282→    if (specBySlug.has(slug)) {
   283→      return {
   284→        sorted: [],
   285→        error: {
   286→          type: "validation",
   287→          message: `Duplicate slug detected: "${slug}". Ensure each spec has a unique slug or title.`,
   288→        },
   289→      };
   290→    }
   291→    specBySlug.set(slug, spec);
   292→    graph.set(slug, []);
   293→  }
   294→
   295→  // Add edges for parent dependencies
   296→  for (const spec of specs) {
   297→    const slug = spec.slug || slugify(spec.title);
   298→    if (spec.parent) {
   299→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   300→
   301→      // Only add edge if parent is in this plan (local reference)
   302→      if (specBySlug.has(parentRef)) {
   303→        const children = graph.get(parentRef) || [];
   304→        children.push(slug);
   305→        graph.set(parentRef, children);
   306→      }
   307→    }
   308→  }
   309→
   310→  // Detect cycles using DFS
   311→  const visited = new Set<string>();
   312→  const recursionStack = new Set<string>();
   313→
   314→  function hasCycle(node: string, path: string[]): string[] | null {
   315→    visited.add(node);
   316→    recursionStack.add(node);
   317→
   318→    const children = graph.get(node) || [];
   319→    for (const child of children) {
   320→      if (!visited.has(child)) {
   321→        const cyclePath = hasCycle(child, [...path, child]);
   322→        if (cyclePath) return cyclePath;
   323→      } else if (recursionStack.has(child)) {
   324→        return [...path, child];
   325→      }
   326→    }
   327→
   328→    recursionStack.delete(node);
   329→    return null;
   330→  }
   331→
   332→  for (const slug of graph.keys()) {
   333→    if (!visited.has(slug)) {
   334→      const cyclePath = hasCycle(slug, [slug]);
   335→      if (cyclePath) {
   336→        const cycleRefs = cyclePath.map(s => `@${s}`).join(" -> ");
   337→        return {
   338→          sorted: [],
   339→          error: {
   340→            type: "circular",
   341→            message: `Circular parent reference: ${cycleRefs}`,
   342→          },
   343→        };
   344→      }
   345→    }
   346→  }
   347→
   348→  // Topological sort using DFS
   349→  const sorted: PlanSpec[] = [];
   350→  const processed = new Set<string>();
   351→
   352→  function visit(node: string) {
   353→    if (processed.has(node)) return;
   354→
   355→    const spec = specBySlug.get(node);
   356→    if (!spec) return;
   357→
   358→    // Visit parent first if it's in this plan
   359→    if (spec.parent) {
   360→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   361→      if (specBySlug.has(parentRef)) {
   362→        visit(parentRef);
   363→      }
   364→    }
   365→
   366→    processed.add(node);
   367→    sorted.push(spec);
   368→  }
   369→
   370→  for (const slug of specBySlug.keys()) {
   371→    visit(slug);
   372→  }
   373→
   374→  return { sorted, error: null };
   375→}
   376→
   377→/**
   378→ * Simple slugification helper
   379→ */
   380→function slugify(title: string): string {
   381→  return title
   382→    .toLowerCase()
   383→    .replace(/[^a-z0-9]+/g, "-")
   384→    .replace(/^-|-$/g, "");
   385→}
   386→
   387→/**
   388→ * Validate parent references.
   389→ *
   390→ * AC: @plan-import ac-17 - Detect missing parent references
   391→ * AC: @plan-import ac-33 - Provide recovery hints
   392→ *
   393→ * @param specs Specs to validate
   394→ * @param existingRefs Set of existing spec refs in the project
   395→ * @returns Errors for specs with invalid parents
   396→ */
   397→export function validateParentRefs(
   398→  specs: PlanSpec[],
   399→  existingRefs: Set<string>,
   400→): ParseError[] {
   401→  const errors: ParseError[] = [];
   402→  const planSlugs = new Set(
   403→    specs.map(s => s.slug || slugify(s.title))
   404→  );
   405→
   406→  for (const spec of specs) {
   407→    if (!spec.parent) continue;
   408→
   409→    const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   410→
   411→    // Check if parent exists in plan or project
   412→    if (!planSlugs.has(parentRef) && !existingRefs.has(parentRef)) {
   413→      errors.push({
   414→        type: "dependency",
   415→        message: `Parent ${spec.parent} not found. Check parent exists or define it earlier in plan`,
   416→        spec,
   417→      });
   418→    }
   419→  }
   420→
   421→  return errors;
   422→}
