            const taskCount = p.derived_tasks.length;
            const tasks =
              taskCount > 0 ? ` [${taskCount} task${taskCount > 1 ? "s" : ""}]` : "";

            console.log(
              `  ${ref} [${p.status}]${tasks} ${p.title}`,
