        // AC: @plan-import ac-15 - Dry run mode
        info(
          `Would create spec: ${specRef} ${spec.parent ? `under ${spec.parent}` : "(root)"}`,
        );
        result.createdSpecs.push(specRef);
      } else {
        // Create spec item
        const specInput: SpecItemInput = {
          title: spec.title,
          type: (spec.type as any) || "feature",
          slugs: [specSlug],
          description: spec.description,
          priority: undefined,
          tags: [],
          depends_on: [],
          implements: [],
          relates_to: [],
          tests: [],
          traits: spec.traits || [],
          notes: [],
        };

        // Add acceptance criteria if present
        if (spec.acceptance_criteria) {
          specInput.acceptance_criteria = spec.acceptance_criteria;
        }

        const newSpec = createSpecItem(specInput);

        // Add spec to parent or create as root
        if (parent) {
          await addChildItem(ctx, parent, newSpec);
        } else {
          // For root specs, need to add to a module file
          // This is a simplification - would need module resolution logic
          throw new Error("Root spec creation not yet implemented");
