  $ kspec plan import ./plan.md --dry-run
  $ kspec plan import ./plan.md --update --json`,
    )
    .action(async (planPath: string, options) => {
      try {
        await importPlan(planPath, options);
      } catch (err) {
        error("Failed to import plan", err);
